import 'package:cached_network_image/cached_network_image.dart';import 'package:flutter/material.dart';import 'package:flutter_riverpod/flutter_riverpod.dart';import 'package:go_router/go_router.dart';import '../../core/error/app_exception.dart';import '../../core/widgets/states.dart';import '../providers/providers.dart';
class HistoryScreen extends ConsumerWidget{const HistoryScreen({super.key});@override Widget build(BuildContext context,WidgetRef ref){final h=ref.watch(historyProvider);return Scaffold(appBar:AppBar(title:const Text('Ko‘rish tarixi'),actions:[IconButton(tooltip:'Tarixni tozalash',onPressed:()async{final ok=await showDialog<bool>(context:context,builder:(c)=>AlertDialog(title:const Text('Tarixni tozalash'),content:const Text('Barcha ko‘rish tarixi o‘chiriladi.'),actions:[TextButton(onPressed:()=>Navigator.pop(c,false),child:const Text('Bekor qilish')),FilledButton(onPressed:()=>Navigator.pop(c,true),child:const Text('Tozalash'))]));if(ok==true){await ref.read(contentRepositoryProvider).clearHistory();ref.invalidate(historyProvider);}},icon:const Icon(Icons.delete_sweep_outlined))]),body:h.when(loading:()=>const AppLoading(),error:(e,_)=>AppErrorView(message:friendlyError(e),onRetry:()=>ref.invalidate(historyProvider)),data:(items)=>items.isEmpty?const Center(child:Text('Ko‘rish tarixi bo‘sh.')):ListView.separated(padding:const EdgeInsets.all(16),itemCount:items.length,itemBuilder:(_,i){final m=items[i];return SizedBox(height:150,child:Row(children:[InkWell(onTap:()=>context.push('/movie/${m.id}'),child:ClipRRect(borderRadius:BorderRadius.circular(12),child:CachedNetworkImage(imageUrl:m.posterUrl,width:88,height:132,fit:BoxFit.cover))),const SizedBox(width:14),Expanded(child:Column(crossAxisAlignment:CrossAxisAlignment.start,mainAxisAlignment:MainAxisAlignment.center,children:[Text(m.title,style:const TextStyle(fontSize:17,fontWeight:FontWeight.bold)),const SizedBox(height:8),Text('${m.progress.toStringAsFixed(0)}% ko‘rildi',style:const TextStyle(color:Colors.grey)),const SizedBox(height:7),LinearProgressIndicator(value:m.progress/100,borderRadius:BorderRadius.circular(4)),const SizedBox(height:10),FilledButton.tonalIcon(onPressed:()=>context.push('/player/${m.id}'),icon:const Icon(Icons.play_arrow,size:18),label:const Text('Davom ettirish'))]))]));},separatorBuilder